if(-not [IO.Path]::GetFullPath($OutDir).StartsWith($frame+'\',[StringComparison]::OrdinalIgnoreCase) -or (Test-Path -LiteralPath $OutDir)){throw 'Fresh private fixture required'}
[IO.Directory]::CreateDirectory($OutDir)|Out-Null
$env:TEMP=$OutDir;$env:TMP=$OutDir
. (Join-Path $Source 'tools\validation\LoadTimes\CleanupOwnership.Common.ps1')
. (Join-Path $Source 'backend\scripts\BrandCompatibility.Common.ps1')
$results=[Collections.Generic.List[object]]::new();$processes=[Collections.Generic.List[object]]::new();$files=[Collections.Generic.List[object]]::new();$taskReceipts=[Collections.Generic.List[object]]::new()
function Assert([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
function Refuses([scriptblock]$Body,[string]$Expected=''){$refused=$false;try{&$Body}catch{if($Expected){Assert ($_.Exception.Message.Contains($Expected)) ('Wrong refusal: '+$_.Exception.Message)};$refused=$true;Add-Content (Join-Path $OutDir 'refusals.log') $_.Exception.Message};Assert $refused 'Expected refusal'}
function Case([string]$Name,[scriptblock]$Body){try{&$Body;$results.Add(@{name=$Name;passed=$true});'PASS '+$Name}catch{$results.Add(@{name=$Name;passed=$false;error=$_.Exception.Message});'FAIL '+$Name+' :: '+$_.Exception.Message}}
function Load([string]$Name){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Source 'tools\validation\Governor\Test-GovernorInstalled.ps1'),[ref]$tokens,[ref]$errors);Assert ($errors.Count -eq 0) 'GI parse';$f=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -ceq $Name},$true));Assert ($f.Count -eq 1) ('Missing exact GI entry '+$Name);Set-Item ('Function:script:'+$Name) ([scriptblock]::Create($f[0].Extent.Text));. ([scriptblock]::Create($f[0].Extent.Text));Set-Item ('Function:script:'+$Name) (Get-Item ('Function:'+$Name)).ScriptBlock}
function Seed-Probe([string]$Name){[IO.Directory]::CreateDirectory((Split-Path (Join-Path $OutDir $Name) -Parent))|Out-Null;$f=Copy-OwnedProbe (Join-Path ([Environment]::SystemDirectory) 'PING.EXE') (Join-Path $OutDir $Name);$files.Add($f.Identity);$f.Dispose();$p=Start-Process $f.Identity.path -ArgumentList '-n','600','127.0.0.1' -WindowStyle Hidden -PassThru;$r=New-OwnedProcess $p;$processes.Add($r);[pscustomobject]@{identity=$r.Identity;file=$f.Identity;original=@{cpuPriority='Normal'};stopped=$false}}
$software=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software');try{$before=ConvertTo-Json @($software.GetValueNames()|Sort-Object|ForEach-Object {@{name=$_;kind=[int]$software.GetValueKind($_);value=$software.GetValue($_,$null,'DoNotExpandEnvironmentNames')}}) -Depth 20 -Compress}finally{$software.Dispose()}
try{
 foreach($name in 'Assert-GiProbeReceipt','Get-GiProbe','Stop-GiProbes','Assert-GiRule','Remove-GiRule','Assert-GiState','Set-StateValue','Save-State','Restore-GiTask','Remove-GiDamagedRule','Invoke-GiCleanup','Check','Start-Probe','Set-GiTaskDisabled','Get-GiTaskWithoutEnabled'){Load $name}
