 Case 'actual-GI-cleanup-all-retained-and-foreign-same-name-survives' {$owned=Seed-Probe 'owned.exe';$secondProcess=Start-Process $owned.file.path -ArgumentList '-n','600','127.0.0.1' -WindowStyle Hidden -PassThru;$secondReceipt=New-OwnedProcess $secondProcess;$processes.Add($secondReceipt);$second=[pscustomobject]@{identity=$secondReceipt.Identity;file=$owned.file;original=@{cpuPriority='Normal'};stopped=$false};$foreign=Seed-Probe 'foreign\RooIndustriesGovernorProbe.exe';$script:probeExe=$owned.file.path;$script:statePath=Join-Path $OutDir 'cleanup-state.json';$script:state=[pscustomobject]@{probes=@($owned,$second)};Stop-GiProbes;Assert ($processes[$processes.Count-3].process.HasExited -and $secondProcess.HasExited -and -not$processes[$processes.Count-1].process.HasExited) 'GI cleanup crossed process ownership';Assert (@($state.probes|Where-Object {-not$_.stopped}).Count -eq 0) 'Prior receipts forgotten'}
