 Case 'actual-GI-damaged-rule-file-changed-refuses' {$script:FixtureId=[Guid]::NewGuid().ToString('N');$script:policyRoot=Join-Path $OutDir 'damaged-private';[IO.Directory]::CreateDirectory((Join-Path $policyRoot 'rules'))|Out-Null;$source=Join-Path $OutDir 'damaged-source.json';[IO.File]::WriteAllText($source,'{ this is not a rule');$path=Join-Path $policyRoot ('rules\damaged-'+$FixtureId+'.json');$f=Copy-OwnedProbe $source $path;$identity=$f.Identity;$f.Dispose();$script:state=[pscustomobject]@{damagedRule=$identity};[IO.File]::WriteAllText($path,'foreign changed bytes');Refuses {Remove-GiDamagedRule};Assert ([IO.File]::ReadAllText($path) -ceq 'foreign changed bytes') 'Actual GI damaged cleanup deleted changed content'}
 Case 'actual-GI-unsupported-modes-refuse-before-mutation' {foreach($phase in 'kill-setup','kill-setup-rerun','legacy-before'){Refuses {& (Join-Path $Source 'tools\validation\Governor\Test-GovernorInstalled.ps1') -Phase $phase -Work 'absent' -Source 'absent' -FixtureId ([Guid]::NewGuid().ToString('N')) -SourceManifestSha256 ('0'*64)} 'cannot prove exclusive child ownership'}}
