 Case 'actual-GI-start-persists-prior-probes-and-stops-on-receipt-write-failure' {$compiled=Join-Path $OutDir 'compiled-sleeper.exe';Add-Type -TypeDefinition 'public static class InstalledOwnershipSleeper { public static void Main(string[] args) { System.Threading.Thread.Sleep(600000); } }' -OutputAssembly $compiled -OutputType ConsoleApplication;$target=Join-Path $OutDir 'receipt-sleeper.exe';$f=Copy-OwnedProbe $compiled $target;$files.Add($f.Identity);$identity=$f.Identity;$f.Dispose();$script:probeExe=$target;$script:state=[pscustomobject]@{probes=@();probeFile=$identity};$script:statePath=Join-Path $OutDir 'write-failure';[IO.Directory]::CreateDirectory($statePath)|Out-Null;function Read-Controls {param($Process)[ordered]@{cpuPriority=[string]$Process.PriorityClass}};Refuses {Start-Probe};Assert ($state.probes.Count -eq 1) 'Created probe receipt absent in memory';$p=Get-GiProbe $state.probes[0];Assert ($null -eq $p -or $p.HasExited) 'Receipt write failure left owned probe alive';$script:statePath=Join-Path $OutDir 'all-probes-state.json';$first=Start-Probe;$firstReceipt=New-OwnedProcess $first;$processes.Add($firstReceipt);$prior=$state.probes[1].identity.creationTimeFileTimeUtc;$second=Start-Probe;$secondReceipt=New-OwnedProcess $second;$processes.Add($secondReceipt);$saved=Get-Content -Raw $statePath|ConvertFrom-Json;Assert ($saved.probes.Count -eq 3 -and $saved.probes[1].identity.creationTimeFileTimeUtc -ceq $prior -and $saved.probes[2].identity.creationTimeFileTimeUtc -ceq $secondReceipt.Identity.creationTimeFileTimeUtc) 'Actual GI start overwrote older ownership receipt';Stop-GiProbes;Assert ($first.HasExited -and $second.HasExited) 'Actual retained probes remain'}
